  1→import { useEffect } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import { authenticate } from "../shopify.server";
  6→import db from "../db.server";
  7→
  8→export const loader = async ({ request }: LoaderFunctionArgs) => {
  9→  const { session } = await authenticate.admin(request);
 10→  const shop = session.shop;
 11→
 12→  const [chartCount, subscription] = await Promise.all([
 13→    db.sizeChart.count({ where: { shop } }),
 14→    db.subscription.findUnique({ where: { shop } }),
 15→  ]);
 16→
 17→  return {
 18→    shop,
 19→    chartCount,
 20→    planId: subscription?.planId ?? "free",
 21→    status: subscription?.status ?? "active",
 22→  };
 23→};
 24→
 25→export const action = async ({ request }: ActionFunctionArgs) => {
 26→  const { session } = await authenticate.admin(request);
 27→  const shop = session.shop;
 28→  const formData = await request.formData();
 29→  const intent = formData.get("intent") as string;
 30→
 31→  try {
 32→    switch (intent) {
 33→      case "export-data": {
 34→        const charts = await db.sizeChart.findMany({ where: { shop }, include: { assignments: true } });
 35→        return { ok: true, message: `Export ready: ${charts.length} charts` };
 36→      }
 37→      case "reset-widget": {
 38→        await db.widgetConfig.deleteMany({ where: { shop } });
 39→        return { ok: true, message: "Widget settings reset to defaults" };
 40→      }
 41→      case "reset-analytics": {
 42→        await db.analyticsEvent.deleteMany({ where: { shop } });
 43→        return { ok: true, message: "Analytics data cleared" };
 44→      }
 45→      default:
 46→        return { error: "Unknown action" };
 47→    }
 48→  } catch (error) {
 49→    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
 50→  }
 51→};
 52→
 53→export default function Settings() {
 54→  const { shop, chartCount, planId, status } = useLoaderData<typeof loader>();
 55→  const fetcher = useFetcher<typeof action>();
 56→  const shopify = useAppBridge();
 57→
 58→  useEffect(() => {
 59→    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Done");
 60→    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
 61→  }, [fetcher.data, shopify]);
 62→
 63→  const isLoading = fetcher.state !== "idle";
 64→
 65→  return (
 66→    <s-page heading="Settings">
 67→      <s-section heading="Account">
 68→        <s-box padding="base" borderWidth="base" borderRadius="base">
 69→          <s-stack direction="inline" gap="base">
 70→            <s-stack direction="block" gap="small-100">
 71→              <s-text tone="neutral">Store</s-text>
 72→              <s-text>{shop}</s-text>
 73→            </s-stack>
 74→            <s-stack direction="block" gap="small-100">
 75→              <s-text tone="neutral">Plan</s-text>
 76→              <s-text>{planId} ({status})</s-text>
 77→            </s-stack>
 78→            <s-stack direction="block" gap="small-100">
 79→              <s-text tone="neutral">Size Charts</s-text>
 80→              <s-text>{chartCount}</s-text>
 81→            </s-stack>
 82→          </s-stack>
 83→        </s-box>
 84→      </s-section>
 85→
 86→      <s-section heading="Data Management">
 87→        <s-box padding="base" borderWidth="base" borderRadius="base">
 88→          <s-stack direction="block" gap="small-200">
 89→            <s-text>Export Size Charts</s-text>
 90→            <s-text tone="neutral">Download all your size charts as JSON data for backup or migration.</s-text>
 91→            <fetcher.Form method="post">
 92→              <input type="hidden" name="intent" value="export-data" />
 93→              <s-button type="submit" loading={isLoading}>Export Data</s-button>
 94→            </fetcher.Form>
 95→          </s-stack>
 96→        </s-box>
 97→      </s-section>
 98→
 99→      <s-section heading="Reset">
100→        <s-stack direction="block" gap="base">
101→          <s-box padding="base" borderWidth="base" borderRadius="base">
102→            <s-stack direction="block" gap="small-200">
103→              <s-text>Reset Widget Settings</s-text>
104→              <s-text tone="neutral">Restore widget appearance to defaults. Charts and data are not affected.</s-text>
105→              <fetcher.Form method="post">
106→                <input type="hidden" name="intent" value="reset-widget" />
107→                <s-button type="submit" tone="critical" loading={isLoading}>Reset Widget</s-button>
108→              </fetcher.Form>
109→            </s-stack>
110→          </s-box>
111→
112→          <s-box padding="base" borderWidth="base" borderRadius="base">
113→            <s-stack direction="block" gap="small-200">
114→              <s-text>Clear Analytics Data</s-text>
115→              <s-text tone="neutral">Remove all analytics events. This cannot be undone.</s-text>
116→              <fetcher.Form method="post">
117→                <input type="hidden" name="intent" value="reset-analytics" />
118→                <s-button type="submit" tone="critical" loading={isLoading}>Clear Analytics</s-button>
119→              </fetcher.Form>
120→            </s-stack>
121→          </s-box>
122→        </s-stack>
123→      </s-section>
124→
125→      <s-section slot="aside" heading="Support">
126→        <s-stack direction="block" gap="small-200">
127→          <s-text tone="neutral">Need help? We respond within 2 hours.</s-text>
128→          <s-unordered-list>
129→            <s-list-item>
130→              <s-link href="mailto:support@sizechartapp.com" target="_blank">Email Support</s-link>
131→            </s-list-item>
132→          </s-unordered-list>
133→        </s-stack>
134→      </s-section>
135→
136→      <s-section slot="aside" heading="App Version">
137→        <s-text tone="neutral">v1.0.0</s-text>
138→        <s-text tone="neutral">Built for Shopify</s-text>
139→      </s-section>
140→    </s-page>
141→  );
142→}
