  1→import { useEffect } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import { authenticate } from "../shopify.server";
  6→import db from "../db.server";
  7→import { getPlan, hasFeature } from "../lib/plans";
  8→
  9→export const loader = async ({ request }: LoaderFunctionArgs) => {
 10→  const { session } = await authenticate.admin(request);
 11→  const shop = session.shop;
 12→
 13→  const [config, subscription] = await Promise.all([
 14→    db.recommenderConfig.findUnique({ where: { shop } }),
 15→    db.subscription.findUnique({ where: { shop } }),
 16→  ]);
 17→
 18→  const plan = getPlan(subscription?.planId ?? "free");
 19→
 20→  return {
 21→    config: config ?? { enabled: false, algorithm: "basic", bodyTypes: "[]", sizingRules: "{}" },
 22→    plan,
 23→    canUseAi: hasFeature(plan.id, "aiRecommender"),
 24→    canUseAdvanced: hasFeature(plan.id, "advancedAi"),
 25→  };
 26→};
 27→
 28→export const action = async ({ request }: ActionFunctionArgs) => {
 29→  const { session } = await authenticate.admin(request);
 30→  const shop = session.shop;
 31→  const formData = await request.formData();
 32→  const intent = formData.get("intent") as string;
 33→
 34→  try {
 35→    switch (intent) {
 36→      case "toggle": {
 37→        const subscription = await db.subscription.findUnique({ where: { shop } });
 38→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
 39→          return { error: "AI recommender requires Growth plan or higher" };
 40→        }
 41→        const current = await db.recommenderConfig.findUnique({ where: { shop } });
 42→        await db.recommenderConfig.upsert({
 43→          where: { shop },
 44→          update: { enabled: !current?.enabled },
 45→          create: { shop, enabled: true },
 46→        });
 47→        return { ok: true, message: current?.enabled ? "AI Recommender disabled" : "AI Recommender enabled" };
 48→      }
 49→      default:
 50→        return { error: "Unknown action" };
 51→    }
 52→  } catch (error) {
 53→    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
 54→  }
 55→};
 56→
 57→export default function Recommender() {
 58→  const { config, plan, canUseAi, canUseAdvanced } = useLoaderData<typeof loader>();
 59→  const fetcher = useFetcher<typeof action>();
 60→  const shopify = useAppBridge();
 61→
 62→  useEffect(() => {
 63→    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Success");
 64→    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
 65→  }, [fetcher.data, shopify]);
 66→
 67→  const isLoading = fetcher.state !== "idle";
 68→
 69→  return (
 70→    <s-page heading="AI Size Recommender">
 71→      {!canUseAi && (
 72→        <s-section>
 73→          <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
 74→            <s-stack direction="block" gap="base">
 75→              <s-heading>Unlock AI Size Recommendations</s-heading>
 76→              <s-paragraph>
 77→                Help customers find their perfect size with AI-powered recommendations
 78→                based on height, weight, and body type. Available on Growth plan and above.
 79→              </s-paragraph>
 80→              <s-button href="/app/pricing" variant="primary">Upgrade to Growth — $9.99/mo</s-button>
 81→            </s-stack>
 82→          </s-box>
 83→        </s-section>
 84→      )}
 85→
 86→      {canUseAi && (
 87→        <s-section heading="Recommender Status">
 88→          <s-box padding="base" borderWidth="base" borderRadius="base">
 89→            <s-stack direction="block" gap="small-200">
 90→              <s-text>Status: {config.enabled ? "Active" : "Disabled"}</s-text>
 91→              <s-text tone="neutral">
 92→                {config.enabled
 93→                  ? "Customers can get AI-powered size recommendations on your storefront"
 94→                  : "Enable to show the 'Find My Size' button on product pages"}
 95→              </s-text>
 96→              <fetcher.Form method="post">
 97→                <input type="hidden" name="intent" value="toggle" />
 98→                <s-button type="submit" variant={config.enabled ? "tertiary" : "primary"} loading={isLoading}>
 99→                  {config.enabled ? "Disable Recommender" : "Enable Recommender"}
100→                </s-button>
101→              </fetcher.Form>
102→            </s-stack>
103→          </s-box>
104→        </s-section>
105→      )}
106→
107→      {canUseAi && (
108→        <s-section heading="How It Works">
109→          <s-stack direction="inline" gap="base">
110→            <s-box padding="base" borderWidth="base" borderRadius="base">
111→              <s-text>1. Customer enters info</s-text>
112→              <s-text tone="neutral">Height, weight, body type, and gender</s-text>
113→            </s-box>
114→            <s-box padding="base" borderWidth="base" borderRadius="base">
115→              <s-text>2. AI analyzes</s-text>
116→              <s-text tone="neutral">Estimates body measurements and matches to your size chart</s-text>
117→            </s-box>
118→            <s-box padding="base" borderWidth="base" borderRadius="base">
119→              <s-text>3. Recommendation</s-text>
120→              <s-text tone="neutral">Shows best size with confidence score and alternatives</s-text>
121→            </s-box>
122→          </s-stack>
123→        </s-section>
124→      )}
125→
126→      {canUseAi && config.enabled && (
127→        <s-section heading="Algorithm">
128→          <s-stack direction="block" gap="base">
129→            <s-box padding="base" borderWidth="base" borderRadius="base">
130→              <s-text>Basic Algorithm</s-text>
131→              <s-text tone="neutral">
132→                Statistical body proportion model. Fast, accurate, no API costs.
133→              </s-text>
134→              <s-text tone="success">{config.algorithm === "basic" ? "Currently active" : "Available"}</s-text>
135→            </s-box>
136→            <s-box padding="base" borderWidth="base" borderRadius="base">
137→              <s-text>Advanced ML Algorithm</s-text>
138→              <s-text tone="neutral">
139→                Improves over time using your store's return data.
140→              </s-text>
141→              {canUseAdvanced
142→                ? <s-text tone="success">{config.algorithm === "advanced" ? "Currently active" : "Available"}</s-text>
143→                : <s-text tone="caution">Requires Pro plan — $19.99/mo</s-text>
144→              }
145→            </s-box>
146→          </s-stack>
147→        </s-section>
148→      )}
149→
150→      {canUseAi && config.enabled && (
151→        <s-section heading="Supported Body Types">
152→          <s-paragraph>These body types are shown to customers in the recommendation form.</s-paragraph>
153→          <s-stack direction="inline" gap="base">
154→            {[
155→              { name: "Slim", desc: "Narrower proportions, fitted preferences" },
156→              { name: "Regular", desc: "Standard proportions, true-to-size" },
157→              { name: "Athletic", desc: "Broader chest/shoulders, narrower waist" },
158→              { name: "Plus", desc: "Fuller proportions, relaxed fit preferences" },
159→            ].map((type) => (
160→              <s-box key={type.name} padding="base" borderWidth="base" borderRadius="base">
161→                <s-text>{type.name}</s-text>
162→                <s-text tone="neutral">{type.desc}</s-text>
163→              </s-box>
164→            ))}
165→          </s-stack>
166→        </s-section>
167→      )}
168→
169→      <s-section slot="aside" heading="Current Plan">
170→        <s-stack direction="block" gap="small-200">
171→          <s-text>{plan.name}</s-text>
172→          <s-text tone="neutral">{canUseAi ? "AI features included" : "AI features not included"}</s-text>
173→          {!canUseAdvanced && canUseAi && (
174→            <s-button href="/app/pricing">Upgrade for Advanced AI</s-button>
175→          )}
176→        </s-stack>
177→      </s-section>
178→
179→      <s-section slot="aside" heading="Performance">
180→        <s-unordered-list>
181→          <s-list-item>Basic: ~5ms response time, $0/use</s-list-item>
182→          <s-list-item>Advanced: ~50ms, $0/use</s-list-item>
183→          <s-list-item>All computation server-side</s-list-item>
184→        </s-unordered-list>
185→      </s-section>
186→    </s-page>
187→  );
188→}
