199→function PositionGrid({
200→  value,
201→  onChange,
202→}: {
203→  value: string;
204→  onChange: (v: string) => void;
205→}) {
206→  const positions = [
207→    { id: "top-left", label: "Top Left" },
208→    { id: "top-right", label: "Top Right" },
209→    { id: "bottom-left", label: "Bottom Left" },
210→    { id: "bottom-right", label: "Bottom Right" },
211→  ];
212→
213→  return (
214→    <div
215→      style={{
216→        display: "grid",
217→        gridTemplateColumns: "1fr 1fr",
218→        gap: "8px",
219→        maxWidth: "320px",
220→      }}
221→    >
222→      {positions.map((pos) => {
223→        const isSelected = value === pos.id;
224→        return (
225→          <s-clickable key={pos.id} onClick={() => onChange(pos.id)}>
226→            <s-box
227→              padding="base"
228→              borderWidth={isSelected ? "large" : "base"}
229→              borderRadius="base"
230→              background={isSelected ? "strong" : undefined}
231→            >
232→              <s-text tone={isSelected ? undefined : "neutral"}>{pos.label}</s-text>
233→            </s-box>
234→          </s-clickable>
235→        );
236→      })}
237→    </div>
238→  );
239→}
