241→function TriggerTypeSelector({
242→  value,
243→  onChange,
244→}: {
245→  value: string;
246→  onChange: (v: string) => void;
247→}) {
248→  const types = [
249→    { id: "button", label: "Button", desc: "Prominent CTA button" },
250→    { id: "link", label: "Link", desc: "Subtle text link" },
251→    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
252→  ];
253→
254→  return (
255→    <s-stack direction="inline" gap="base">
256→      {types.map((t) => {
257→        const isSelected = value === t.id;
258→        return (
259→          <s-clickable key={t.id} onClick={() => onChange(t.id)}>
260→            <s-box
261→              padding="base"
262→              borderWidth={isSelected ? "large" : "base"}
263→              borderRadius="base"
