            <s-text color="subdued">AI features not included</s-text>
            <s-button href="/app/pricing" variant="primary">Upgrade plan</s-button>
          </s-stack>
        </s-section>

        <s-section slot="aside" heading="Performance">
          <s-unordered-list>
            <s-list-item>Basic algorithm: ~5ms response</s-list-item>
            <s-list-item>Advanced ML: ~50ms response</s-list-item>
            <s-list-item>All server-side — $0/recommendation</s-list-item>
          </s-unordered-list>
        </s-section>
      </s-page>
    );
  }

  // -----------------------------------------------------------------------
  // FULL PAGE — plan allows AI
  // -----------------------------------------------------------------------
  return (
    <s-page heading="AI Size Recommender">

      {/* Primary action */}
