                    </s-badge>
                  </s-stack>
                  {testResult.alternatives.length > 0 && (
                    <s-stack direction="inline" gap="small-200">
                      <s-text color="subdued">Alternatives:</s-text>
                      {testResult.alternatives.map((alt) => (
                        <s-badge key={alt} tone="neutral">{alt}</s-badge>
                      ))}
                    </s-stack>
                  )}
                  <s-divider />
                  <s-text color="subdued">Estimated measurements</s-text>
                  <s-stack direction="inline" gap="base">
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Bust</s-text>
                      <s-text>{testResult.bust} cm</s-text>
                    </s-stack>
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Waist</s-text>
                      <s-text>{testResult.waist} cm</s-text>
                    </s-stack>
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Hips</s-text>
                      <s-text>{testResult.hips} cm</s-text>
                    </s-stack>
                  </s-stack>
                </s-stack>
              </s-box>
            )}
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Current Plan                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Current Plan">
        <s-stack direction="block" gap="small-200">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone="success">{plan.name}</s-badge>
            <s-text color="subdued">${plan.price}/mo</s-text>
          </s-stack>
          <s-unordered-list>
            <s-list-item>
              <s-text color="subdued">Basic AI recommender</s-text>
              <s-badge tone="success">Included</s-badge>
            </s-list-item>
            <s-list-item>
              <s-text color="subdued">Advanced ML</s-text>
              <s-badge tone={canUseAdvanced ? "success" : "neutral"}>
                {canUseAdvanced ? "Included" : "Pro only"}
              </s-badge>
            </s-list-item>
          </s-unordered-list>
          {!canUseAdvanced && (
            <s-button href="/app/pricing">Upgrade for Advanced ML</s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Performance Stats                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Performance">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">All computation is server-side. No third-party API calls means zero added latency and zero per-recommendation cost.</s-text>
          <s-unordered-list>
            <s-list-item>Basic algorithm: ~5ms response</s-list-item>
            <s-list-item>Advanced ML: ~50ms response</s-list-item>
            <s-list-item>Cost per recommendation: $0</s-list-item>
            <s-list-item>No customer data stored</s-list-item>
          </s-unordered-list>
          <s-badge tone="success">GDPR compliant</s-badge>
        </s-stack>
      </s-section>

    </s-page>
  );
}
